// Fallback product photos from the shop's price-list spreadsheet (model → image link).
//
// Used only when a product has no usable `product_images` row — i.e. it is not
// matched to TikTok (or the match was removed). Once a product is matched, the
// TikTok sync writes a 'found' row and that photo wins automatically.
//
// The links are bundled with the app (src/data, regenerated by
// scripts/build-image-fallbacks.py) and the photos load straight from the
// brand site, so this adds no Supabase reads or egress.

import data from '../data/product-image-fallbacks.json';
import { normalizeCode, KNOWN_SKU_SUFFIXES } from './fuzzy-match.js';

// Longest first so "AVDF" is tried before "DF".
const SUFFIXES = [...KNOWN_SKU_SUFFIXES].filter(s => s.length > 1).sort((a, b) => b.length - a.length);

function linkFor(key) {
  const path = data.images[key];
  if (!path) return null;
  return /^https?:\/\//.test(path) ? path : data.prefix + path;
}

/**
 * Spreadsheet image link for a product name / model code, or null.
 * Tries the exact model first, then the model with a distributor suffix
 * (DR, VDF, …) removed — "GA-2100-1ADR" → "GA-2100-1A".
 */
export function fallbackImageUrl(name) {
  const key = normalizeCode(name);
  if (!key) return null;
  const exact = linkFor(key);
  if (exact) return exact;
  for (const s of SUFFIXES) {
    if (key.length > s.length + 3 && key.endsWith(s)) {
      const hit = linkFor(key.slice(0, -s.length));
      if (hit) return hit;
    }
  }
  return null;
}
